export class ImageMediaError extends Error{constructor(code,message,details={}){super(message);this.name='ImageMediaError';this.code=code;this.details=details;}}
const fail=(c,m,d={})=>{throw new ImageMediaError(c,m,d)};const finite=v=>typeof v==='number'&&Number.isFinite(v);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function normalizeAsset(input={}){const width=+input.width,height=+input.height;if(!finite(width)||!finite(height)||width<=0||height<=0)fail('IMAGE_DIMENSIONS','asset requires positive dimensions');if(width*height>100_000_000)fail('IMAGE_PIXEL_LIMIT','asset exceeds 100MP decode policy',{width,height});return Object.freeze({id:String(input.id??'asset'),width,height,mime:String(input.mime??'image/png'),provenance:String(input.provenance??'user'),source:String(input.source??'local')});}
export function normalizeCrop(crop={x:0,y:0,width:1,height:1}){const vals=['x','y','width','height'].map(k=>+crop[k]);if(vals.some(v=>!finite(v)))fail('IMAGE_CROP','crop must be finite');let[x,y,width,height]=vals;if(width<=0||height<=0||x<0||y<0||x+width>1+1e-9||y+height>1+1e-9)fail('IMAGE_CROP','crop must lie in normalized asset coordinates');return Object.freeze({x,y,width,height});}
export function assetToView(point,crop,view){crop=normalizeCrop(crop);const x=(point.x-crop.x)/crop.width*view.width,y=(point.y-crop.y)/crop.height*view.height;return{x,y};}
export function viewToAsset(point,crop,view){crop=normalizeCrop(crop);return{x:crop.x+(point.x/view.width)*crop.width,y:crop.y+(point.y/view.height)*crop.height};}
export function prepareAnnotation(a={}){const x=+a.x,y=+a.y;if(!finite(x)||!finite(y)||x<0||x>1||y<0||y>1)fail('IMAGE_ANNOTATION','annotation coordinates must be normalized asset coordinates');return Object.freeze({id:String(a.id??'annotation'),x,y,label:String(a.label??''),kind:String(a.kind??'callout'),provenance:String(a.provenance??'user')});}
const allowedTags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','text','tspan','defs','clipPath','linearGradient','radialGradient','stop','title','desc']);
const allowedAttrs=new Set(['xmlns','viewBox','width','height','x','y','x1','y1','x2','y2','cx','cy','r','rx','ry','d','points','fill','fill-opacity','stroke','stroke-width','stroke-opacity','opacity','transform','font-size','font-weight','text-anchor','dominant-baseline','clip-path','offset','stop-color','stop-opacity','role','aria-label']);
export function sanitizeSvg(svg){let s=String(svg??'');if(/<!DOCTYPE|<!ENTITY/i.test(s))fail('SVG_ENTITY','SVG entities/doctype are forbidden');s=s.replace(/<\s*(script|foreignObject|iframe|object|embed|audio|video|image|use|animate|set|style)\b[\s\S]*?<\/\s*\1\s*>/gi,'').replace(/<\s*(script|foreignObject|iframe|object|embed|audio|video|image|use|animate|set|style)\b[^>]*\/?\s*>/gi,'');
 s=s.replace(/<([A-Za-z][\w:-]*)([^>]*)>/g,(all,tag,attrs)=>{if(!allowedTags.has(tag))return'';let kept='';attrs.replace(/([\w:-]+)\s*=\s*("[^"]*"|'[^']*')/g,(m,n,q)=>{const name=n;if(/^on/i.test(name)||!allowedAttrs.has(name))return'';const val=q.slice(1,-1);if(/(?:javascript:|data:text\/html|https?:|file:|\\)/i.test(val))return'';if(name==='clip-path'&&!/^url\(#[\w.-]+\)$/.test(val))return'';kept+=` ${name}="${val.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}"`;return'';});return`<${tag}${kept}>`;});
 if(!/^\s*<svg\b/i.test(s))fail('SVG_ROOT','sanitized SVG must have svg root');return s;}
export function prepareImagePlan(input={}){const asset=normalizeAsset(input.asset),crop=normalizeCrop(input.crop);const annotations=Object.freeze((input.annotations??[]).map(prepareAnnotation));return Object.freeze({asset,crop,annotations,mode:String(input.mode??'fit'),sanitizedSvg:input.svg?sanitizeSvg(input.svg):null});}
